for row in d['browser']:
 target='Detail' if row['path'].endswith(' → applicantDetail') else 'List';s+=f"| {row['profile']} | {row['size']:,} | {target} / {row['condition']} | {change(row,'sourceUsefulMs')} | {change(row,'clickMs')} | {change(row,'sourceRequests')} | {change(row,'requestCount')} | {change(row,'encodedBodyBytes')} |\n"
