for key,label in [('readTtfbMs','Protected read TTFB ms'),('server_totalMs','Server total ms'),('server_identityMs','Identity verification ms'),('server_live_sessionMs','Live-session check ms'),('server_transaction_acquireMs','Observable transaction acquisition ms'),('server_databaseMs','Database span ms'),('server_serializationMs','Serialization ms'),('readTransferMs','Transfer ms'),('networkCompleteMs','Drain ms'),('scriptMs','Browser script ms'),('taskMs','Browser task ms')]:s+=f'| {label} | {change(local,key)} | {change(five,key)} |\n'
