for key,label in [('readTtfbMs','Protected read TTFB ms'),('server_totalMs','Server total ms'),('server_identityMs','Identity verification ms'),('server_live_sessionMs','Live-session check ms'),('server_transaction_acquireMs','Observable transaction acquisition ms'),('server_databaseMs','Database span ms'),('server_transactionMs','Transaction span ms'),('server_serializationMs','Serialization ms'),('readTransferMs','Transfer ms')]:s+=f'| {label} | {change(local_list,key)} | {change(list_five,key)} |\n'
s+='\n| Constrained main source observations, including warmups | Baseline | Candidate |\n|---|---:|---:|\n'
pipeline_account={v:next(a for a in transport['routeBodyAccounting'] if a['profile']=='constrained' and a['category']=='main' and a['variant']==v and a['stage']=='source' and a['route']=='/api/workspace?kind=pipelinePage') for v in ['B','A']}
for key,label in [('requests','Captured pipelinePage requests'),('observedEncodedBodyBytes','Observed pipelinePage response body bytes'),('unknownBodySnapshots','PipelinePage unknown-byte snapshots')]:s+=f"| {label} | {pipeline_account['B'][key]:,} | {pipeline_account['A'][key]:,} |\n"
auth_counts={v:sum(a['count'] for a in transport['authorityEventCounts'] if a['profile']=='constrained' and a['category']=='main' and a['variant']==v and a['stage']=='source' and a['kind']=='auth') for v in ['B','A']}
s+=f"| Recorded source Auth epoch notifications | {auth_counts['B']} | {auth_counts['A']} |\n"
known_obsolete={v:sum(a['sourceOutcomes'] for a in transport['sourcePipelineReadMultiplicity'] if a['profile']=='constrained' and a['category']=='main' and a['variant']==v and a['protectedPipelineReads']>1 and a['lastAuthBeforeFirstSelectedDispatch'] and a['readAuthorityCauseObserved']) for v in ['B','A']}
s+=f"| Multiple-read source preparations with all observed Auth notifications before first selected-effect marker and readAuthority change recorded | {known_obsolete['B']} | {known_obsolete['A']} |\n"

s+='\nEach main timed entry/detail retains exactly one protected pipeline read. Database and transaction phases overlap and must not be summed. Database spans include Prisma/transport/scheduling; transaction acquisition is not an isolated pool wait. No server query or identity-validation change is claimed. CLS distributions, authority causes, source read multiplicities and incomplete byte snapshots remain in the accompanying JSON.\n'
s+='\n## Deferred-feature costs retained from Phase11\n\n| Destination / visit | Source before → after ms | Click before → after ms | Source+click before → after ms | Click requests before → after | Click bytes before → after |\n|---|---:|---:|---:|---:|---:|\n'
for row in d['features']:s+=f"| {row['path']} / {row['condition']} | {change(row,'sourceUsefulMs')} | {change(row,'clickMs')} | {change(row,'sourcePlusClickMs')} | {change(row,'requestCount')} | {change(row,'encodedBodyBytes')} |\n"
